package com.example.uploads.service;

import com.example.uploads.config.UploadProperties;
import com.example.uploads.exception.UploadSecurityException;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Locale;
import java.util.Set;

@Service
public class FileDownloadService {

    private static final Set<String> ALLOWED_CONTENT_TYPES = Set.of(
            MediaType.TEXT_PLAIN_VALUE,
            MediaType.APPLICATION_PDF_VALUE,
            MediaType.IMAGE_PNG_VALUE,
            MediaType.IMAGE_JPEG_VALUE
    );

    private final UploadProperties uploadProperties;

    public FileDownloadService(UploadProperties uploadProperties) {
        this.uploadProperties = uploadProperties;
    }

    public DownloadedFile loadFile(String requestedFileName) {
        String sanitizedFileName = sanitizeFileName(requestedFileName);
        validateAllowedExtension(sanitizedFileName);

        Path uploadDir = canonicalizeDirectory(Paths.get(uploadProperties.getDirectory()));
        Path targetFile = resolveAndValidateTarget(uploadDir, sanitizedFileName);

        ensureReadableRegularFile(targetFile);

        String contentType = detectContentType(sanitizedFileName);
        validateContentType(contentType);

        byte[] content = readFile(targetFile);
        return new DownloadedFile(sanitizedFileName, contentType, content);
    }

    private String sanitizeFileName(String fileName) {
        if (fileName == null || fileName.isBlank()) {
            throw new UploadSecurityException("fileName must not be empty");
        }

        String normalized = fileName.replace('\\', '/');
        String baseName = normalized.substring(normalized.lastIndexOf('/') + 1);

        if (baseName.isBlank()
                || baseName.contains("..")
                || baseName.contains("/")
                || baseName.contains("\0")) {
            throw new UploadSecurityException("Invalid file name");
        }

        return baseName;
    }

    private void validateAllowedExtension(String fileName) {
        String extension = extractExtension(fileName);
        if (extension.isEmpty() || uploadProperties.getAllowedExtensions() == null
                || uploadProperties.getAllowedExtensions().stream()
                .map(ext -> ext.toLowerCase(Locale.ROOT))
                .noneMatch(ext -> ext.equals(extension))) {
            throw new UploadSecurityException("File extension is not allowed");
        }
    }

    private String extractExtension(String fileName) {
        int dotIndex = fileName.lastIndexOf('.');
        if (dotIndex < 0 || dotIndex == fileName.length() - 1) {
            return "";
        }
        return fileName.substring(dotIndex + 1).toLowerCase(Locale.ROOT);
    }

    private Path canonicalizeDirectory(Path path) {
        try {
            Path realPath = path.toRealPath(LinkOption.NOFOLLOW_LINKS);
            if (!Files.isDirectory(realPath)) {
                throw new UploadSecurityException("Upload directory is invalid");
            }
            return realPath;
        } catch (IOException e) {
            throw new UploadSecurityException("Failed to canonicalize path", e);
        }
    }

    private Path resolveAndValidateTarget(Path uploadDir, String sanitizedFileName) {
        Path targetFile = uploadDir.resolve(sanitizedFileName).normalize();

        if (!targetFile.startsWith(uploadDir)) {
            throw new UploadSecurityException("Path traversal attempt detected");
        }

        try {
            Path realTarget = targetFile.toRealPath(LinkOption.NOFOLLOW_LINKS);
            if (!realTarget.startsWith(uploadDir)) {
                throw new UploadSecurityException("Path traversal attempt detected");
            }
            return realTarget;
        } catch (IOException e) {
            throw new UploadSecurityException("Failed to resolve target file", e);
        }
    }

    private void ensureReadableRegularFile(Path targetFile) {
        if (!Files.exists(targetFile, LinkOption.NOFOLLOW_LINKS)
                || !Files.isRegularFile(targetFile, LinkOption.NOFOLLOW_LINKS)
                || !Files.isReadable(targetFile)) {
            throw new UploadSecurityException("File not found or not readable");
        }
    }

    private String detectContentType(String fileName) {
        String extension = extractExtension(fileName);
        return switch (extension) {
            case "txt" -> MediaType.TEXT_PLAIN_VALUE;
            case "pdf" -> MediaType.APPLICATION_PDF_VALUE;
            case "png" -> MediaType.IMAGE_PNG_VALUE;
            case "jpg", "jpeg" -> MediaType.IMAGE_JPEG_VALUE;
            default -> "application/octet-stream";
        };
    }

    private void validateContentType(String contentType) {
        if (!ALLOWED_CONTENT_TYPES.contains(contentType)) {
            throw new UploadSecurityException("Content type is not allowed");
        }
    }

    private byte[] readFile(Path file) {
        try (InputStream inputStream = Files.newInputStream(file);
             ByteArrayOutputStream outputStream = new ByteArrayOutputStream()) {

            byte[] buffer = new byte[8192];
            int read;
            while ((read = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, read);
            }
            return outputStream.toByteArray();
        } catch (IOException e) {
            throw new UploadSecurityException("Failed to read file", e);
        }
    }

    public record DownloadedFile(String fileName, String contentType, byte[] content) {
    }
}
