package com.example.uploads.controller;

import com.example.uploads.service.FileDownloadService;
import com.example.uploads.service.FileDownloadService.DownloadedFile;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.nio.charset.StandardCharsets;

@RestController
public class FileDownloadController {

    private final FileDownloadService fileDownloadService;

    public FileDownloadController(FileDownloadService fileDownloadService) {
        this.fileDownloadService = fileDownloadService;
    }

    @GetMapping("/api/files")
    public ResponseEntity<byte[]> downloadFile(@RequestParam("fileName") String fileName) {
        DownloadedFile downloadedFile = fileDownloadService.loadFile(fileName);

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.parseMediaType(downloadedFile.contentType()));
        headers.setContentDisposition(ContentDisposition.attachment()
                .filename(downloadedFile.fileName(), StandardCharsets.UTF_8)
                .build());

        return ResponseEntity.ok()
                .headers(headers)
                .body(downloadedFile.content());
    }
}
