package com.example.securefiles.web;

import com.example.securefiles.service.DocumentDownloadService;
import java.io.IOException;
import org.springframework.core.io.Resource;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/documents")
public class DocumentDownloadController {

    private final DocumentDownloadService documentDownloadService;

    public DocumentDownloadController(DocumentDownloadService documentDownloadService) {
        this.documentDownloadService = documentDownloadService;
    }

    @GetMapping("/download")
    public ResponseEntity<Resource> download(@RequestParam("file") String file) throws IOException {
        Resource resource = documentDownloadService.loadAsResource(file);

        String filename = resource.getFilename() != null ? resource.getFilename() : "download";
        ContentDisposition contentDisposition = ContentDisposition.attachment().filename(filename).build();

        return ResponseEntity.ok()
                .header(HttpHeaders.CONTENT_DISPOSITION, contentDisposition.toString())
                .contentType(MediaType.APPLICATION_OCTET_STREAM)
                .body(resource);
    }
}
