"}, {"type": "CODE_BLOCK", "language": "java", "content": "// DocumentDownloadService.java
package com.example.securefiles.service;

import com.example.securefiles.web.FileAccessDeniedException;
import com.example.securefiles.web.FileNotFoundException;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.InvalidPathException;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.springframework.core.io.Resource;
import org.springframework.core.io.UrlResource;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;

@Service
public class DocumentDownloadService {

    private final Path baseDirectory;

    public DocumentDownloadService() {
        this.baseDirectory = Paths.get("data", "docs").toAbsolutePath().normalize();
    }

    public Resource loadAsResource(String file) throws IOException {
        if (!StringUtils.hasText(file)) {
            throw new FileAccessDeniedException("Invalid file parameter.");
        }

        final Path requestedPath;
        try {
            requestedPath = Paths.get(file).getFileName();
        } catch (InvalidPathException ex) {
            throw new FileAccessDeniedException("Invalid file parameter.");
        }

        if (requestedPath == null || requestedPath.toString().isBlank()) {
            throw new FileAccessDeniedException("Invalid file parameter.");
        }

        Path resolvedPath = baseDirectory.resolve(requestedPath).normalize();

        if (!resolvedPath.startsWith(baseDirectory)) {
            throw new FileAccessDeniedException("Path traversal attempt detected.");
        }

        if (!Files.exists(resolvedPath) || !Files.isRegularFile(resolvedPath)) {
            throw new FileNotFoundException("Requested file not found.");
        }

        Path baseRealPath = baseDirectory.toRealPath();
        Path fileRealPath = resolvedPath.toRealPath();

        if (!fileRealPath.startsWith(baseRealPath)) {
            throw new FileAccessDeniedException("Access outside allowed directory is denied.");
        }

        return new UrlResource(fileRealPath.toUri());
    }
}
