package com.example.tools.controller;

import com.example.tools.service.PingService;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/tools")
public class PingController {

    private final PingService pingService;

    public PingController(PingService pingService) {
        this.pingService = pingService;
    }

    @GetMapping(value = "/ping", produces = MediaType.TEXT_PLAIN_VALUE)
    public ResponseEntity<String> ping(
            @RequestParam("target") @NotBlank String target,
            @RequestParam(value = "count", defaultValue = "4") @Min(1) @Max(10) int count,
            HttpServletRequest request) {

        String clientIp = request.getRemoteAddr();
        String result = pingService.ping(target, count, clientIp);
        return ResponseEntity.ok(result);
    }
}
