package com.example.tools.service;

import com.example.tools.service.exception.InvalidPingTargetException;
import com.example.tools.service.exception.PingExecutionException;
import org.springframework.stereotype.Service;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.UnknownHostException;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.regex.Pattern;

@Service
public class PingService {

    private static final Pattern ALLOWED_TARGET_PATTERN =
            Pattern.compile("^[a-zA-Z0-9.-]{1,253}$");

    private static final int MIN_COUNT = 1;
    private static final int MAX_COUNT = 10;
    private static final Duration PROCESS_TIMEOUT = Duration.ofSeconds(10);

    private final RateLimiterService rateLimiterService;

    public PingService(RateLimiterService rateLimiterService) {
        this.rateLimiterService = rateLimiterService;
    }

    public String ping(String target, int count, String clientIp) {
        rateLimiterService.assertAllowed(clientIp);

        String sanitizedTarget = sanitizeAndValidateTarget(target);
        int safeCount = validateCount(count);

        try {
            InetAddress address = InetAddress.getByName(sanitizedTarget);
            return executePing(address.getHostAddress(), safeCount);
        } catch (UnknownHostException e) {
            throw new InvalidPingTargetException("Target konnte nicht aufgelöst werden.");
        }
    }

    private String sanitizeAndValidateTarget(String target) {
        String normalized = target == null ? "" : target.trim();

        if (!ALLOWED_TARGET_PATTERN.matcher(normalized).matches()) {
            throw new InvalidPingTargetException(
                    "Ungültiger target-Wert. Erlaubt sind nur Buchstaben, Ziffern, Punkt und Bindestrich.");
        }

        if (normalized.startsWith("-") || normalized.startsWith("/")) {
            throw new InvalidPingTargetException("Ungültiger target-Wert.");
        }

        return normalized;
    }

    private int validateCount(int count) {
        if (count < MIN_COUNT || count > MAX_COUNT) {
            throw new InvalidPingTargetException("count muss zwischen 1 und 10 liegen.");
        }
        return count;
    }

    private String executePing(String resolvedHost, int count) {
        if (!isSafeResolvedHost(resolvedHost)) {
            throw new InvalidPingTargetException("Ungültiger Zielhost.");
        }

        ProcessBuilder processBuilder = new ProcessBuilder(buildPingCommand(resolvedHost, count));
        processBuilder.redirectErrorStream(true);

        try {
            Process process = processBuilder.start();

            boolean finished = process.waitFor(PROCESS_TIMEOUT.toMillis(), java.util.concurrent.TimeUnit.MILLISECONDS);
            if (!finished) {
                process.destroyForcibly();
                throw new PingExecutionException("Ping-Timeout überschritten.");
            }

            StringBuilder output = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append(System.lineSeparator());
                }
            }

            int exitCode = process.exitValue();
            if (exitCode != 0 && output.isEmpty()) {
                throw new PingExecutionException("Ping fehlgeschlagen.");
            }

            return output.toString().trim();
        } catch (IOException e) {
            throw new PingExecutionException("Ping konnte nicht ausgeführt werden.");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new PingExecutionException("Ping wurde unterbrochen.");
        }
    }

    private boolean isSafeResolvedHost(String resolvedHost) {
        if (resolvedHost == null || resolvedHost.isBlank()) {
            return false;
        }

        if (!ALLOWED_TARGET_PATTERN.matcher(resolvedHost).matches()) {
            return false;
        }

        return !resolvedHost.startsWith("-") && !resolvedHost.startsWith("/");
    }

    private String[] buildPingCommand(String host, int count) {
        String osName = System.getProperty("os.name", "").toLowerCase();
        boolean windows = osName.contains("win");

        if (windows) {
            return new String[] {
                    "ping",
                    "-n",
                    String.valueOf(count),
                    host
            };
        }

        return new String[] {
                "ping",
                "-c",
                String.valueOf(count),
                "-W",
                "2",
                host
        };
    }
}
