"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimiterService.java
package com.example.tools.service;

import com.example.tools.service.exception.RateLimitExceededException;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Service
public class RateLimiterService {

    private static final int MAX_REQUESTS = 10;
    private static final Duration WINDOW = Duration.ofMinutes(1);

    private final Map<String, Deque<Instant>> requestsByClient = new ConcurrentHashMap<>();

    public void assertAllowed(String clientIp) {
        String key = clientIp == null ? "unknown" : clientIp;

        Deque<Instant> timestamps = requestsByClient.computeIfAbsent(key, k -> new ArrayDeque<>());
        synchronized (timestamps) {
            Instant now = Instant.now();
            Instant cutoff = now.minus(WINDOW);

            while (!timestamps.isEmpty() && timestamps.peekFirst().isBefore(cutoff)) {
                timestamps.removeFirst();
            }

            if (timestamps.size() >= MAX_REQUESTS) {
                throw new RateLimitExceededException("Zu viele Anfragen. Bitte später erneut versuchen.");
            }

            timestamps.addLast(now);
        }
    }
}
