### 6) Service mit Validierung, Sanitizing und Logging

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GuestbookService.java
package com.example.guestbook.service;

import com.example.guestbook.domain.GuestbookEntry;
import com.example.guestbook.repository.GuestbookEntryRepository;
import com.example.guestbook.web.dto.GuestbookEntryRequest;
import com.example.guestbook.web.dto.GuestbookEntryView;
import java.time.Instant;
import java.util.List;
import java.util.regex.Pattern;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

@Service
public class GuestbookService {

    private static final Logger log = LoggerFactory.getLogger(GuestbookService.class);

    private static final Pattern NAME_PATTERN = Pattern.compile("^[\\p{L}0-9 .,'\\-]{1,80}$");
    private static final Pattern TEXT_PATTERN = Pattern.compile("^[\\p{L}0-9 .,'\\-!?()】【：;:/@#&+_\\n\\r]{1,1000}$");

    private final GuestbookEntryRepository repository;

    public GuestbookService(GuestbookEntryRepository repository) {
        this.repository = repository;
    }

    @Transactional
    public GuestbookEntryView createEntry(GuestbookEntryRequest request, String authenticatedUsername) {
        String name = normalize(request.getName());
        String text = normalize(request.getText());

        validateInput(name, text, authenticatedUsername);

        GuestbookEntry saved = repository.save(new GuestbookEntry(name, text, Instant.now()));
        log.info("Guestbook entry created by user='{}', entryId={}", authenticatedUsername, saved.getId());

        return new GuestbookEntryView(saved.getName(), saved.getText(), saved.getCreatedAt());
    }

    @Transactional(readOnly = true)
    public List<GuestbookEntryView> getAllEntries() {
        return repository.findAllByOrderByCreatedAtDesc()
                .stream()
                .map(e -> new GuestbookEntryView(e.getName(), e.getText(), e.getCreatedAt()))
                .toList();
    }

    private void validateInput(String name, String text, String authenticatedUsername) {
        if (!StringUtils.hasText(name) || !StringUtils.hasText(text)) {
            log.warn("Rejected guestbook entry from user='{}' due to empty fields", authenticatedUsername);
            throw new InvalidGuestbookEntryException("Name and text must not be empty.");
        }

        if (name.length() > 80 || text.length() > 1000) {
            log.warn("Rejected guestbook entry from user='{}' due to length violation", authenticatedUsername);
            throw new InvalidGuestbookEntryException("Input exceeds allowed length.");
        }

        if (!NAME_PATTERN.matcher(name).matches()) {
            log.warn("Rejected guestbook entry from user='{}' due to invalid name pattern", authenticatedUsername);
            throw new InvalidGuestbookEntryException("Invalid characters in name.");
        }

        if (!TEXT_PATTERN.matcher(text).matches()) {
            log.warn("Rejected guestbook entry from user='{}' due to invalid text pattern", authenticatedUsername);
            throw new InvalidGuestbookEntryException("Invalid characters in text.");
        }

        if (containsSuspiciousControlCharacters(name) || containsSuspiciousControlCharacters(text)) {
            log.warn("Rejected guestbook entry from user='{}' due to control characters", authenticatedUsername);
            throw new InvalidGuestbookEntryException("Control characters are not allowed.");
        }
    }

    private boolean containsSuspiciousControlCharacters(String value) {
        return value.chars().anyMatch(ch -> ch < 0x20 && ch != '\n' && ch != '\r' && ch != '\t');
    }

    private String normalize(String value) {
        return value == null ? "" : value.strip();
    }
}
