package com.example.guestbook.web;

import com.example.guestbook.service.GuestbookService;
import com.example.guestbook.web.dto.GuestbookEntryRequest;
import jakarta.validation.Valid;
import java.security.Principal;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;

@Controller
@RequestMapping("/guestbook")
public class GuestbookController {

    private final GuestbookService guestbookService;

    public GuestbookController(GuestbookService guestbookService) {
        this.guestbookService = guestbookService;
    }

    @GetMapping(produces = MediaType.TEXT_HTML_VALUE)
    public String showGuestbook(Model model) {
        model.addAttribute("entries", guestbookService.getAllEntries());
        return "guestbook";
    }

    @PostMapping(consumes = MediaType.APPLICATION_FORM_URLENCODED_VALUE)
    public String addEntry(@Valid GuestbookEntryRequest request, Principal principal) {
        guestbookService.createEntry(request, principal.getName());
        return "redirect:/guestbook";
    }
}
