"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SearchInputValidator.java
package com.example.customersearch.service.validation;

import org.springframework.stereotype.Component;

import java.text.Normalizer;
import java.util.regex.Pattern;

@Component
public class SearchInputValidator {

    private static final int MAX_LENGTH = 100;
    private static final Pattern ALLOWED_PATTERN = Pattern.compile("^[\\p{L}\\p{N} .,'@\\-_/]+$");

    public String validateAndNormalize(String input) {
        if (input == null) {
            throw new IllegalArgumentException("search must not be null");
        }

        String normalized = Normalizer.normalize(input, Normalizer.Form.NFKC).trim();

        if (normalized.isEmpty()) {
            throw new IllegalArgumentException("search must not be empty");
        }

        if (normalized.length() > MAX_LENGTH) {
            throw new IllegalArgumentException("search exceeds maximum length");
        }

        if (!ALLOWED_PATTERN.matcher(normalized).matches()) {
            throw new IllegalArgumentException("search contains invalid characters");
        }

        return normalized;
    }
}
