package com.example.customersearch.persistence;

import com.example.customersearch.web.dto.CustomerDto;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;

@Repository
public class JdbcCustomerRepository implements CustomerRepository {

    private final NamedParameterJdbcTemplate jdbcTemplate;

    public JdbcCustomerRepository(NamedParameterJdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public List<CustomerDto> searchByNameEmailOrCity(String searchTerm) {
        String sql = """
                SELECT id, name, email, city
                FROM customers
                WHERE LOWER(name) LIKE LOWER(:searchPattern)
                   OR LOWER(email) LIKE LOWER(:searchPattern)
                   OR LOWER(city) LIKE LOWER(:searchPattern)
                ORDER BY name ASC
                """;

        MapSqlParameterSource params = new MapSqlParameterSource()
                .addValue("searchPattern", "%" + searchTerm + "%");

        return jdbcTemplate.query(sql, params, (rs, rowNum) -> new CustomerDto(
                rs.getLong("id"),
                rs.getString("name"),
                rs.getString("email"),
                rs.getString("city")
        ));
    }
}
