package com.example.directory.ldap;

import com.example.directory.api.dto.DirectoryUserDto;
import java.util.List;
import javax.naming.NamingException;
import javax.naming.directory.Attributes;
import org.springframework.ldap.core.AttributesMapper;
import org.springframework.ldap.core.LdapTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class LdapDirectoryUserRepository implements DirectoryUserRepository {

    private final LdapTemplate ldapTemplate;

    public LdapDirectoryUserRepository(LdapTemplate ldapTemplate) {
        this.ldapTemplate = ldapTemplate;
    }

    @Override
    public List<DirectoryUserDto> findByUsername(String username) {
        String baseDn = "ou=users,dc=example,dc=com";
        String filter = "(&(objectClass=person)(uid={0}))";

        return ldapTemplate.search(baseDn, filter, new Object[]{username}, userAttributesMapper());
    }

    private AttributesMapper<DirectoryUserDto> userAttributesMapper() {
        return (Attributes attributes) -> {
            String username = getAttributeValue(attributes, "uid");
            String displayName = getAttributeValue(attributes, "displayName");
            String email = getAttributeValue(attributes, "mail");
            String department = getAttributeValue(attributes, "department");

            return new DirectoryUserDto(username, displayName, email, department);
        };
    }

    private String getAttributeValue(Attributes attributes, String attributeName) throws NamingException {
        if (attributes.get(attributeName) == null) {
            return null;
        }
        Object value = attributes.get(attributeName).get();
        return value != null ? value.toString() : null;
    }
}
