package com.example.directory.service;

import com.example.directory.api.dto.DirectoryUserDto;
import com.example.directory.ldap.DirectoryUserRepository;
import com.example.directory.service.exception.DirectoryLookupException;
import com.example.directory.service.exception.InvalidUsernameException;
import java.util.List;
import java.util.regex.Pattern;
import org.springframework.stereotype.Service;

@Service
public class DefaultDirectoryUserService implements DirectoryUserService {

    private static final Pattern USERNAME_PATTERN = Pattern.compile("^[a-zA-Z0-9._-]{1,64}$");

    private final DirectoryUserRepository repository;

    public DefaultDirectoryUserService(DirectoryUserRepository repository) {
        this.repository = repository;
    }

    @Override
    public List<DirectoryUserDto> searchUsers(String username) {
        validateUsername(username);

        try {
            return repository.findByUsername(username);
        } catch (RuntimeException ex) {
            throw new DirectoryLookupException("LDAP lookup failed", ex);
        }
    }

    private void validateUsername(String username) {
        if (username == null || username.isBlank()) {
            throw new InvalidUsernameException("username must not be blank");
        }
        if (!USERNAME_PATTERN.matcher(username).matches()) {
            throw new InvalidUsernameException("username contains invalid characters");
        }
    }
}
