"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ExportService.java
package com.example.export.service;

import com.example.export.web.ExportFileNotFoundException;
import com.example.export.web.InvalidExportFilenameException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Pattern;

@Service
public class ExportService {

    private static final Pattern SAFE_FILENAME = Pattern.compile("^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$");

    private final Path exportsDirectory;

    public ExportService(@Value("${app.exports-directory:exports}") String exportsDirectory) {
        this.exportsDirectory = Paths.get(exportsDirectory).toAbsolutePath().normalize();
    }

    public ResponseEntity<byte[]> buildDownloadResponse(String filename) {
        String validatedFilename = validateFilename(filename);
        Path requestedFile = resolveAndVerifyFile(validatedFilename);

        byte[] fileContent = readFileContent(requestedFile);

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_OCTET_STREAM);
        headers.setContentLength(fileContent.length);
        headers.setContentDisposition(ContentDisposition.attachment().filename(validatedFilename).build());

        // Sicherer Header für die Frontend-Nutzung ohne Offenlegung interner Pfade
        headers.add("X-Download-Filename", validatedFilename);

        return ResponseEntity.ok()
                .headers(headers)
                .body(fileContent);
    }

    private String validateFilename(String filename) {
        if (filename == null || filename.isBlank()) {
            throw new InvalidExportFilenameException("Invalid filename.");
        }

        if (!SAFE_FILENAME.matcher(filename).matches()) {
            throw new InvalidExportFilenameException("Invalid filename.");
        }

        return filename;
    }

    private Path resolveAndVerifyFile(String filename) {
        Path candidate = exportsDirectory.resolve(filename).normalize();

        if (!candidate.startsWith(exportsDirectory)) {
            throw new InvalidExportFilenameException("Invalid filename.");
        }

        if (!Files.exists(candidate) || !Files.isRegularFile(candidate)) {
            throw new ExportFileNotFoundException("File not found.");
        }

        return candidate;
    }

    private byte[] readFileContent(Path file) {
        try {
            return Files.readAllBytes(file);
        } catch (IOException ex) {
            throw new ExportFileNotFoundException("File not found.");
        }
    }
}
