"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectService.java
package com.example.redirect.service;

import com.example.redirect.config.RedirectTargetRegistry;
import com.example.redirect.exception.InvalidRedirectTargetException;
import com.example.redirect.ratelimit.RateLimitExceededException;
import com.example.redirect.ratelimit.RateLimiterService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.util.regex.Pattern;

@Service
public class RedirectService {

    private static final Pattern SAFE_KEY_PATTERN = Pattern.compile("^[a-zA-Z0-9_-]{1,50}$");

    private final RedirectTargetRegistry redirectTargetRegistry;
    private final RateLimiterService rateLimiterService;

    public RedirectService(RedirectTargetRegistry redirectTargetRegistry,
                           RateLimiterService rateLimiterService) {
        this.redirectTargetRegistry = redirectTargetRegistry;
        this.rateLimiterService = rateLimiterService;
    }

    public ResponseEntity<Void> buildRedirectResponse(String redirectUrl, HttpServletRequest request) {
        String clientKey = resolveClientKey(request);
        rateLimiterService.assertAllowed(clientKey);

        String normalizedKey = normalizeAndValidateKey(redirectUrl);
        URI target = redirectTargetRegistry.resolveTarget(normalizedKey)
                .orElseThrow(() -> new InvalidRedirectTargetException("Redirect target is not allowed."));

        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(target);

        return new ResponseEntity<>(headers, HttpStatus.FOUND);
    }

    private String normalizeAndValidateKey(String redirectUrl) {
        if (redirectUrl == null) {
            throw new InvalidRedirectTargetException("redirectUrl must not be null.");
        }

        String trimmed = redirectUrl.trim();
        if (!SAFE_KEY_PATTERN.matcher(trimmed).matches()) {
            throw new InvalidRedirectTargetException("redirectUrl contains invalid characters.");
        }

        return trimmed;
    }

    private String resolveClientKey(HttpServletRequest request) {
        String forwardedFor = request.getHeader("X-Forwarded-For");
        if (forwardedFor != null && !forwardedFor.isBlank()) {
            return forwardedFor.split(",")[0].trim();
        }
        return request.getRemoteAddr();
    }
}
