"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimiterService.java
package com.example.redirect.ratelimit;

import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.Instant;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

@Service
public class RateLimiterService {

    private static final int MAX_REQUESTS = 30;
    private static final Duration WINDOW = Duration.ofMinutes(1);

    private final ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();

    public void assertAllowed(String clientKey) {
        Bucket bucket = buckets.computeIfAbsent(clientKey, key -> new Bucket(Instant.now(), new AtomicInteger(0)));

        synchronized (bucket) {
            Instant now = Instant.now();
            if (Duration.between(bucket.windowStart(), now).compareTo(WINDOW) > 0) {
                bucket.windowStart = now;
                bucket.counter.set(0);
            }

            int current = bucket.counter.incrementAndGet();
            if (current > MAX_REQUESTS) {
                throw new RateLimitExceededException("Too many requests. Please try again later.");
            }
        }
    }

    private static final class Bucket {
        private Instant windowStart;
        private final AtomicInteger counter;

        private Bucket(Instant windowStart, AtomicInteger counter) {
            this.windowStart = windowStart;
            this.counter = counter;
        }

        private Instant windowStart() {
            return windowStart;
        }
    }
}
