"}, {"type": "CODE_BLOCK", "language": "java", "content": "// TargetValidationService.java
package com.example.secureproxy.target;

import org.springframework.stereotype.Service;

import java.net.InetAddress;
import java.net.URI;
import java.util.Locale;
import java.util.Set;

@Service
public class TargetValidationService {

    public void validate(TargetDefinition target) {
        URI uri = target.baseUri();

        if (!"https".equalsIgnoreCase(uri.getScheme())) {
            throw new TargetNotAllowedException("Only HTTPS targets are allowed.");
        }

        String host = uri.getHost();
        if (host == null || host.isBlank()) {
            throw new TargetNotAllowedException("Target host is missing.");
        }

        String normalizedHost = host.toLowerCase(Locale.ROOT);

        if (!target.allowedHostnames().contains(normalizedHost)) {
            throw new TargetNotAllowedException("Host is not in the trusted hostname allowlist.");
        }

        validateResolvedIpAgainstAllowlist(normalizedHost, target.allowedIpAddresses());
    }

    private void validateResolvedIpAgainstAllowlist(String host, Set<String> allowedIpAddresses) {
        try {
            InetAddress[] resolved = InetAddress.getAllByName(host);
            for (InetAddress address : resolved) {
                String ip = address.getHostAddress();
                if (!allowedIpAddresses.contains(ip)) {
                    throw new TargetNotAllowedException("Resolved IP is not in the trusted IP allowlist.");
                }
            }
        } catch (Exception ex) {
            throw new TargetNotAllowedException("Failed to resolve target host securely.");
        }
    }
}
