"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureTlsHttpClientConfig.java
package com.example.secureproxy.http;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.client.RestClient;

import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLParameters;
import java.net.http.HttpClient;
import java.time.Duration;

@Configuration
public class SecureTlsHttpClientConfig {

    @Bean
    public RestClient secureRestClient() {
        HttpClient httpClient = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(5))
                .sslContext(secureSslContext())
                .sslParameters(secureSslParameters())
                .followRedirects(HttpClient.Redirect.NEVER)
                .build();

        return RestClient.builder()
                .requestFactory(new JdkClientHttpRequestFactory(httpClient))
                .build();
    }

    private SSLContext secureSslContext() {
        try {
            SSLContext context = SSLContext.getInstance("TLSv1.2");
            context.init(null, null, null);
            return context;
        } catch (Exception ex) {
            throw new IllegalStateException("Unable to initialize TLS 1.2 context.", ex);
        }
    }

    private SSLParameters secureSslParameters() {
        SSLParameters parameters = new SSLParameters();
        parameters.setProtocols(new String[]{"TLSv1.3", "TLSv1.2"});
        parameters.setCipherSuites(new String[]{
                "TLS_AES_256_GCM_SHA384",
                "TLS_AES_128_GCM_SHA256",
                "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
                "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256"
        });
        return parameters;
    }
}
