package com.example.secureproxy.service;

import com.example.secureproxy.target.TargetDefinition;
import com.example.secureproxy.target.TargetValidationService;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;

@Service
public class OutboundFetchService {

    private final RestClient secureRestClient;
    private final TargetValidationService targetValidationService;

    public OutboundFetchService(RestClient secureRestClient,
                                TargetValidationService targetValidationService) {
        this.secureRestClient = secureRestClient;
        this.targetValidationService = targetValidationService;
    }

    public String fetch(TargetDefinition target) {
        targetValidationService.validate(target);

        return secureRestClient.get()
                .uri(target.baseUri())
                .accept(MediaType.APPLICATION_JSON)
                .retrieve()
                .body(String.class);
    }
}
