package com.example.secureproxy.web;

import com.example.secureproxy.service.OutboundFetchService;
import com.example.secureproxy.target.TargetDefinition;
import com.example.secureproxy.target.TargetNotAllowedException;
import com.example.secureproxy.target.TargetRegistry;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ProxyController {

    private final TargetRegistry targetRegistry;
    private final OutboundFetchService outboundFetchService;

    public ProxyController(TargetRegistry targetRegistry,
                           OutboundFetchService outboundFetchService) {
        this.targetRegistry = targetRegistry;
        this.outboundFetchService = outboundFetchService;
    }

    @GetMapping("/api/fetch")
    public ResponseEntity<String> fetch(@RequestParam("targetId") String targetId) {
        TargetDefinition target = targetRegistry.findByTargetId(targetId)
                .orElseThrow(() -> new TargetNotAllowedException("Unknown targetId."));

        String body = outboundFetchService.fetch(target);
        return ResponseEntity.ok(body);
    }
}
