"}, {"type": "CODE_BLOCK", "language": "java", "content": "// Sha256FingerprintService.java
package com.example.fingerprint.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.stereotype.Service;

@Service
public class Sha256FingerprintService implements FingerprintService {

    private static final int SHORT_HASH_LENGTH = 16;

    @Override
    public String createFingerprint(String value) {
        String normalized = value == null ? "" : value.trim();

        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(normalized.getBytes(StandardCharsets.UTF_8));
            return toHex(hashBytes).substring(0, SHORT_HASH_LENGTH);
        } catch (NoSuchAlgorithmException ex) {
            // SHA-256 ist in jeder modernen Java-Umgebung verfügbar.
            // Falls dennoch ein Konfigurationsproblem vorliegt, wird bewusst eine
            // generische RuntimeException geworfen, ohne interne Details preiszugeben.
            throw new IllegalStateException("Fingerprint service is unavailable.");
        }
    }

    private String toHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(Character.forDigit((b >>> 4) & 0xF, 16));
            sb.append(Character.forDigit(b & 0xF, 16));
        }
        return sb.toString();
    }
}
