package com.example.notes.service;

import com.example.notes.api.dto.EncryptNoteRequest;
import com.example.notes.api.dto.EncryptNoteResponse;
import com.example.notes.crypto.AesGcmCryptoService;
import com.example.notes.crypto.UserIdValidator;
import org.springframework.stereotype.Service;

import java.nio.charset.StandardCharsets;
import java.util.Objects;

@Service
public class NoteEncryptionService {

    private final AesGcmCryptoService cryptoService;
    private final UserIdValidator userIdValidator;

    public NoteEncryptionService(AesGcmCryptoService cryptoService, UserIdValidator userIdValidator) {
        this.cryptoService = cryptoService;
        this.userIdValidator = userIdValidator;
    }

    public EncryptNoteResponse encrypt(EncryptNoteRequest request) {
        Objects.requireNonNull(request, "request must not be null");

        String text = request.text();
        if (text == null || text.isBlank()) {
            throw new IllegalArgumentException("text must not be blank");
        }

        String userId = request.userId();
        if (userId == null || userId.isBlank()) {
            userId = "anonymous";
        }

        userIdValidator.validate(userId);

        byte[] aad = userId.getBytes(StandardCharsets.UTF_8);
        String encrypted = cryptoService.encryptToBase64(text, aad);

        return new EncryptNoteResponse(userId, encrypted);
    }
}
