### 7) Crypto Service

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// AesGcmCryptoService.java
package com.example.notes.crypto;

import org.springframework.stereotype.Service;

import javax.crypto.Cipher;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Base64;

@Service
public class AesGcmCryptoService {

    private static final String CIPHER_ALGORITHM = "AES/GCM/NoPadding";
    private static final int GCM_TAG_LENGTH_BITS = 128;
    private static final int IV_LENGTH_BYTES = 12;

    private final SecretKeyProvider secretKeyProvider;
    private final SecureRandom secureRandom;

    public AesGcmCryptoService(SecretKeyProvider secretKeyProvider) {
        this.secretKeyProvider = secretKeyProvider;
        this.secureRandom = new SecureRandom();
    }

    public String encryptToBase64(String plaintext, byte[] aad) {
        try {
            SecretKey key = secretKeyProvider.getEncryptionKey();

            byte[] iv = new byte[IV_LENGTH_BYTES];
            secureRandom.nextBytes(iv);

            Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, key, new GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv));
            cipher.updateAAD(aad);

            byte[] ciphertext = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));

            byte[] combined = ByteBuffer.allocate(iv.length + ciphertext.length)
                    .put(iv)
                    .put(ciphertext)
                    .array();

            return Base64.getEncoder().encodeToString(combined);
        } catch (Exception ex) {
            throw new CryptoOperationException("Encryption failed", ex);
        }
    }
}
