### 9) Java KeyStore-basierter Key Provider

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// KeyStoreSecretKeyProvider.java
package com.example.notes.crypto;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.io.InputStream;
import java.security.KeyStore;
import java.util.Base64;

@Component
public class KeyStoreSecretKeyProvider implements SecretKeyProvider {

    private final SecretKey encryptionKey;

    public KeyStoreSecretKeyProvider(
            @Value("${app.crypto.keystore-location}") String keystoreLocation,
            @Value("${app.crypto.keystore-password}") String keystorePassword,
            @Value("${app.crypto.key-alias}") String keyAlias,
            @Value("${app.crypto.key-password}") String keyPassword
    ) {
        this.encryptionKey = loadKey(keystoreLocation, keystorePassword, keyAlias, keyPassword);
    }

    @Override
    public SecretKey getEncryptionKey() {
        return encryptionKey;
    }

    private SecretKey loadKey(String keystoreLocation, String keystorePassword, String keyAlias, String keyPassword) {
        try (InputStream inputStream = getClass().getClassLoader().getResourceAsStream(keystoreLocation)) {
            if (inputStream == null) {
                throw new IllegalStateException("Keystore not found on classpath: " + keystoreLocation);
            }

            KeyStore keyStore = KeyStore.getInstance("PKCS12");
            keyStore.load(inputStream, keystorePassword.toCharArray());

            KeyStore.ProtectionParameter protectionParameter =
                    new KeyStore.PasswordProtection(keyPassword.toCharArray());

            KeyStore.SecretKeyEntry secretKeyEntry =
                    (KeyStore.SecretKeyEntry) keyStore.getEntry(keyAlias, protectionParameter);

            if (secretKeyEntry == null) {
                throw new IllegalStateException("No secret key entry found for alias: " + keyAlias);
            }

            SecretKey secretKey = secretKeyEntry.getSecretKey();
            if (!"AES".equalsIgnoreCase(secretKey.getAlgorithm())) {
                throw new IllegalStateException("Unexpected key algorithm: " + secretKey.getAlgorithm());
            }

            return new SecretKeySpec(secretKey.getEncoded(), "AES");
        } catch (Exception ex) {
            throw new IllegalStateException("Failed to load encryption key from keystore", ex);
        }
    }
}
