### 5) Sichere JDBC-Implementierung mit parameterisierten Queries

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// JdbcOrderRepository.java
package com.example.partnercallback.repository.jdbc;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Optional;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import com.example.partnercallback.domain.OrderRecord;
import com.example.partnercallback.repository.OrderRepository;
import com.example.partnercallback.service.dto.OrderCallbackCommand;

@Repository
public class JdbcOrderRepository implements OrderRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcOrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public Optional<OrderRecord> findByOrderId(String orderId) {
        String sql = """
                SELECT id, order_id, status, amount, updated_at
                FROM orders
                WHERE order_id = ?
                """;

        return jdbcTemplate.query(sql, new OrderRowMapper(), orderId)
                .stream()
                .findFirst();
    }

    @Override
    public OrderRecord upsertByOrderId(OrderCallbackCommand command) {
        Optional<OrderRecord> existing = findByOrderId(command.getOrderId());

        if (existing.isPresent()) {
            String updateSql = """
                    UPDATE orders
                    SET status = ?, amount = ?, updated_at = CURRENT_TIMESTAMP
                    WHERE order_id = ?
                    """;
            jdbcTemplate.update(updateSql, command.getStatus(), command.getAmount(), command.getOrderId());
            return findByOrderId(command.getOrderId())
                    .orElseThrow(() -> new IllegalStateException("Order disappeared after update"));
        }

        String insertSql = """
                INSERT INTO orders (order_id, status, amount, updated_at)
                VALUES (?, ?, ?, CURRENT_TIMESTAMP)
                """;
        jdbcTemplate.update(insertSql, command.getOrderId(), command.getStatus(), command.getAmount());

        return findByOrderId(command.getOrderId())
                .orElseThrow(() -> new IllegalStateException("Order could not be created"));
    }

    private static class OrderRowMapper implements RowMapper<OrderRecord> {
        @Override
        public OrderRecord mapRow(ResultSet rs, int rowNum) throws SQLException {
            OffsetDateTime updatedAt = null;
            Timestamp ts = rs.getTimestamp("updated_at");
            if (ts != null) {
                updatedAt = ts.toInstant().atOffset(ZoneOffset.UTC);
            }

            return new OrderRecord(
                    rs.getLong("id"),
                    rs.getString("order_id"),
                    rs.getString("status"),
                    rs.getBigDecimal("amount"),
                    updatedAt
            );
        }
    }
}
