"}, {"type": "CODE_BLOCK", "language": "java", "content": "// PartnerCallbackService.java
package com.example.partnercallback.service;

import java.math.BigDecimal;
import java.util.Locale;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import com.example.partnercallback.domain.OrderRecord;
import com.example.partnercallback.repository.OrderRepository;
import com.example.partnercallback.service.dto.OrderCallbackCommand;

@Service
public class PartnerCallbackService {

    private final OrderRepository orderRepository;

    public PartnerCallbackService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @Transactional
    public OrderRecord handleCallback(OrderCallbackCommand command) {
        String normalizedOrderId = normalizeOrderId(command.getOrderId());
        String normalizedStatus = normalizeStatus(command.getStatus());
        BigDecimal normalizedAmount = normalizeAmount(command.getAmount());

        OrderCallbackCommand normalizedCommand = new OrderCallbackCommand(
                normalizedOrderId,
                normalizedStatus,
                normalizedAmount
        );

        return orderRepository.upsertByOrderId(normalizedCommand);
    }

    private String normalizeOrderId(String orderId) {
        return orderId == null ? null : orderId.trim();
    }

    private String normalizeStatus(String status) {
        return status == null ? null : status.trim().toUpperCase(Locale.ROOT);
    }

    private BigDecimal normalizeAmount(BigDecimal amount) {
        return amount == null ? null : amount.stripTrailingZeros();
    }
}
