package com.example.settings.service;

import com.example.settings.api.dto.ApplicationSettingsResponse;
import com.example.settings.api.dto.ApplicationSettingsUpdateRequest;
import com.example.settings.domain.ApplicationSettings;
import com.example.settings.persistence.ApplicationSettingsRepository;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;

import java.util.LinkedHashMap;
import java.util.Map;

@Service
public class ApplicationSettingsService {

    private final ApplicationSettingsRepository repository;
    private final ObjectMapper objectMapper;

    public ApplicationSettingsService(ApplicationSettingsRepository repository, ObjectMapper objectMapper) {
        this.repository = repository;
        this.objectMapper = objectMapper;
    }

    @Transactional
    public ApplicationSettingsResponse updateSettings(ApplicationSettingsUpdateRequest request) {
        ApplicationSettings settings = repository.findById("global").orElseGet(ApplicationSettings::new);

        if (StringUtils.hasText(request.getDefaultRole())) {
            settings.setDefaultRole(request.getDefaultRole().trim());
        }

        if (request.getMaxRefundAmount() != null) {
            settings.setMaxRefundAmount(request.getMaxRefundAmount());
        }

        if (request.getFeatureFlags() != null) {
            settings.setFeatureFlagsJson(toSafeJson(validateFeatureFlags(request.getFeatureFlags())));
        }

        if (StringUtils.hasText(request.getSupportEmail())) {
            settings.setSupportEmail(request.getSupportEmail().trim().toLowerCase());
        }

        if (request.getMaintenanceMode() != null) {
            settings.setMaintenanceMode(request.getMaintenanceMode());
        }

        repository.save(settings);
        return toResponse(settings);
    }

    @Transactional
    public ApplicationSettingsResponse getSettings() {
        ApplicationSettings settings = repository.findById("global").orElseGet(ApplicationSettings::new);
        return toResponse(settings);
    }

    private Map<String, Boolean> validateFeatureFlags(Map<String, Boolean> input) {
        Map<String, Boolean> sanitized = new LinkedHashMap<>();
        for (Map.Entry<String, Boolean> entry : input.entrySet()) {
            String key = entry.getKey();
            if (!StringUtils.hasText(key)) {
                throw new InvalidSettingsException("featureFlags contains an empty key");
            }
            String trimmedKey = key.trim();
            if (!trimmedKey.matches("^[a-zA-Z0-9._-]{1,64}$")) {
                throw new InvalidSettingsException("featureFlags contains an invalid key");
            }
            sanitized.put(trimmedKey, Boolean.TRUE.equals(entry.getValue()));
        }
        return sanitized;
    }

    private String toSafeJson(Map<String, Boolean> featureFlags) {
        try {
            return objectMapper.writeValueAsString(featureFlags);
        } catch (JsonProcessingException e) {
            throw new InvalidSettingsException("featureFlags could not be serialized");
        }
    }

    private ApplicationSettingsResponse toResponse(ApplicationSettings settings) {
        Map<String, Boolean> flags;
        try {
            @SuppressWarnings("unchecked")
            Map<String, Boolean> parsed = objectMapper.readValue(settings.getFeatureFlagsJson(), Map.class);
            flags = parsed;
        } catch (Exception e) {
            flags = Map.of();
        }

        return new ApplicationSettingsResponse(
                settings.getDefaultRole(),
                settings.getMaxRefundAmount(),
                flags,
                settings.getSupportEmail(),
                settings.isMaintenanceMode()
        );
    }
}
