## 7) Secure Cart Deserializer

Dieser Deserializer akzeptiert nur das erwartete JSON-Schema und verhindert, dass Jackson beliebige Typen oder unerwartete Strukturen verarbeitet.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartDtoDeserializer.java
package com.example.cart.infrastructure.serialization;

import com.example.cart.api.dto.CartDto;
import com.example.cart.api.dto.CartItemDto;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.ObjectCodec;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class CartDtoDeserializer extends StdDeserializer<CartDto> {

    public CartDtoDeserializer() {
        super(CartDto.class);
    }

    @Override
    public CartDto deserialize(JsonParser parser, DeserializationContext ctxt) throws IOException {
        ObjectCodec codec = parser.getCodec();
        JsonNode root = codec.readTree(parser);

        JsonNode itemsNode = root.get("items");
        if (itemsNode == null || !itemsNode.isArray()) {
            throw ctxt.weirdStringException(root.toString(), CartDto.class, "Expected 'items' array");
        }

        List<CartItemDto> items = new ArrayList<>();
        for (JsonNode itemNode : itemsNode) {
            JsonNode articleIdNode = itemNode.get("articleId");
            JsonNode quantityNode = itemNode.get("quantity");

            if (articleIdNode == null || !articleIdNode.isTextual()) {
                throw ctxt.weirdStringException(itemNode.toString(), CartItemDto.class, "Expected textual 'articleId'");
            }
            if (quantityNode == null || !quantityNode.canConvertToInt()) {
                throw ctxt.weirdStringException(itemNode.toString(), CartItemDto.class, "Expected numeric 'quantity'");
            }

            String articleId = articleIdNode.asText();
            int quantity = quantityNode.asInt();

            items.add(new CartItemDto(articleId, quantity));
        }

        return new CartDto(List.copyOf(items));
    }
}
