## 11) Secure Service Implementation

Hier passieren Base64-Decoding, JSON-Parsing, Validierung, serverseitige Artikelauflösung und Summenberechnung.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartServiceImpl.java
package com.example.cart.application;

import com.example.cart.api.dto.CartDto;
import com.example.cart.api.dto.CartItemResponse;
import com.example.cart.api.dto.CartResponse;
import com.example.cart.domain.Article;
import com.example.cart.domain.ArticleRepository;
import com.example.cart.infrastructure.exception.BadCartRequestException;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.ConstraintViolation;
import jakarta.validation.Validator;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

@Service
public class CartServiceImpl implements CartService {

    private final ObjectMapper objectMapper;
    private final Validator validator;
    private final ArticleRepository articleRepository;

    public CartServiceImpl(ObjectMapper objectMapper, Validator validator, ArticleRepository articleRepository) {
        this.objectMapper = objectMapper;
        this.validator = validator;
        this.articleRepository = articleRepository;
    }

    @Override
    public CartResponse loadCart(String encodedCart) {
        final byte[] decodedBytes;
        try {
            decodedBytes = Base64.getDecoder().decode(encodedCart);
        } catch (IllegalArgumentException ex) {
            throw new BadCartRequestException("Invalid Base64 input");
        }

        final String json = new String(decodedBytes, StandardCharsets.UTF_8);

        final CartDto cart;
        try {
            cart = objectMapper.readValue(json, CartDto.class);
        } catch (Exception ex) {
            throw new BadCartRequestException("Invalid cart payload");
        }

        Set<ConstraintViolation<CartDto>> violations = validator.validate(cart);
        if (!violations.isEmpty()) {
            throw new BadCartRequestException("Cart validation failed");
        }

        List<String> articleIds = cart.items().stream()
                .map(item -> item.articleId())
                .distinct()
                .toList();

        List<Article> articles = articleRepository.findAllById(articleIds);
        Map<String, Article> articleMap = new HashMap<>();
        for (Article article : articles) {
            articleMap.put(article.id(), article);
        }

        List<CartItemResponse> responseItems = cart.items().stream()
                .map(item -> {
                    Article article = articleMap.get(item.articleId());
                    if (article == null) {
                        throw new BadCartRequestException("Unknown article referenced in cart");
                    }

                    BigDecimal lineTotal = article.price().multiply(BigDecimal.valueOf(item.quantity()));
                    return new CartItemResponse(
                            article.id(),
                            article.name(),
                            item.quantity(),
                            article.price(),
                            lineTotal
                    );
                })
                .toList();

        BigDecimal totalSum = responseItems.stream()
                .map(CartItemResponse::lineTotal)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        return new CartResponse(responseItems, totalSum);
    }
}
