### `RedirectService.java`
"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectService.java
package com.example.redirect.service;

import com.example.redirect.config.RedirectPolicy;
import com.example.redirect.exception.InvalidRedirectTargetException;
import java.net.URI;
import java.net.URISyntaxException;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;

@Service
public class RedirectService {

    private final RedirectPolicy redirectPolicy;

    public RedirectService(RedirectPolicy redirectPolicy) {
        this.redirectPolicy = redirectPolicy;
    }

    public URI resolveTarget(String rawUrl) {
        if (!StringUtils.hasText(rawUrl)) {
            return redirectPolicy.defaultStartPage();
        }

        final URI candidate;
        try {
            candidate = new URI(rawUrl.trim()).normalize();
        } catch (URISyntaxException ex) {
            throw new InvalidRedirectTargetException("Ungültige Redirect-URL.", ex);
        }

        if (!candidate.isAbsolute()) {
            throw new InvalidRedirectTargetException("Relative Redirect-URLs sind nicht erlaubt.");
        }

        String scheme = candidate.getScheme();
        String host = candidate.getHost();

        if (scheme == null || host == null) {
            throw new InvalidRedirectTargetException("Redirect-URL muss ein gültiges Schema und Host enthalten.");
        }

        if (!redirectPolicy.isAllowedScheme(scheme) || !redirectPolicy.isAllowedHost(host)) {
            throw new InvalidRedirectTargetException("Redirect-Ziel ist nicht erlaubt.");
        }

        return candidate;
    }
}
