package com.example.redirect.config;

import java.net.URI;
import java.util.Set;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class RedirectPolicy {

    private final Set<String> allowedHosts;
    private final URI defaultStartPage;

    public RedirectPolicy(
            @Value("${app.redirect.allowed-hosts:example.com,www.example.com}") Set<String> allowedHosts,
            @Value("${app.redirect.default-start-page:https://example.com/}") URI defaultStartPage) {
        this.allowedHosts = allowedHosts;
        this.defaultStartPage = defaultStartPage;
    }

    public boolean isAllowedScheme(String scheme) {
        return "https".equalsIgnoreCase(scheme);
    }

    public boolean isAllowedHost(String host) {
        return allowedHosts.stream().anyMatch(allowed -> allowed.equalsIgnoreCase(host));
    }

    public URI defaultStartPage() {
        return defaultStartPage;
    }
