"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectAuditService.java
package com.example.redirect.service;

import jakarta.servlet.http.HttpServletRequest;
import java.net.URI;
import java.util.Objects;
import java.util.regex.Pattern;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class RedirectAuditService {

    private static final Logger log = LoggerFactory.getLogger(RedirectAuditService.class);

    private static final Pattern CONTROL_CHARS = Pattern.compile("[\\r\\n\\t\\f\\u0000-\\u001F\\u007F]");
    private static final int MAX_LOG_VALUE_LENGTH = 512;

    public void logRedirect(HttpServletRequest request, String requestedUrl, URI resolvedTarget) {
        String clientIp = sanitizeForLog(request != null ? request.getRemoteAddr() : null);
        String userAgent = sanitizeForLog(request != null ? request.getHeader("User-Agent") : null);
        String safeRequestedUrl = sanitizeForLog(requestedUrl);
        String safeResolvedTarget = sanitizeForLog(resolvedTarget != null ? resolvedTarget.toString() : null);

        log.info("Redirect audit: clientIp={}, userAgent={}, requestedUrl={}, resolvedTarget={}",
                clientIp,
                userAgent,
                safeRequestedUrl,
                safeResolvedTarget);
    }

    private String sanitizeForLog(String value) {
        if (value == null) {
            return "";
        }

        String sanitized = CONTROL_CHARS.matcher(value).replaceAll("_");
        sanitized = sanitized.replace('\u2028', '_').replace('\u2029', '_');
        if (sanitized.length() > MAX_LOG_VALUE_LENGTH) {
            sanitized = sanitized.substring(0, MAX_LOG_VALUE_LENGTH) + "...";
        }
        return Objects.requireNonNullElse(sanitized, "");
    }
}
