### 3) XML-Verarbeitung mit Sicherheitskontrollen

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SafeXmlProcessor.java
package com.example.xmlapi.xml;

import com.example.xmlapi.web.XmlResponse;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.xml.bind.JAXBContext;
import jakarta.xml.bind.Unmarshaller;
import org.springframework.stereotype.Component;

import javax.xml.XMLConstants;
import javax.xml.bind.JAXBException;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;

import java.io.StringReader;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.List;
import java.util.Set;

@Component
public class SafeXmlProcessor {

    private static final Set<String> ALLOWED_HOSTS = Set.of("example.com");
    private static final int MAX_XML_LENGTH = 100_000;

    private final ObjectMapper objectMapper;

    public SafeXmlProcessor(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    public XmlResponse process(String xmlData) {
        validateInputSize(xmlData);

        Document document = parseSecurely(xmlData);

        XmlPayload payload = extractPayload(document);

        List<String> resolvedReferences = payload.references().stream()
                .map(this::resolveWhitelistedReference)
                .toList();

        XmlResponse response = new XmlResponse(
                payload.id(),
                payload.title(),
                resolvedReferences
        );

        return response;
    }

    private void validateInputSize(String xmlData) {
        if (xmlData == null || xmlData.isBlank()) {
            throw new IllegalArgumentException("XML darf nicht leer sein.");
        }
        if (xmlData.length() > MAX_XML_LENGTH) {
            throw new IllegalArgumentException("XML ist zu groß.");
        }
    }

    private Document parseSecurely(String xmlData) {
        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            dbf.setXIncludeAware(false);
            dbf.setExpandEntityReferences(false);
            dbf.setNamespaceAware(true);

            var builder = dbf.newDocumentBuilder();
            builder.setEntityResolver((publicId, systemId) -> new InputSource(new StringReader("")));

            return builder.parse(new InputSource(new StringReader(xmlData)));
        } catch (ParserConfigurationException | SAXException e) {
            throw new IllegalArgumentException("Unsicheres oder ungültiges XML wurde abgelehnt.", e);
        } catch (Exception e) {
            throw new IllegalArgumentException("XML konnte nicht verarbeitet werden.", e);
        }
    }

    private XmlPayload extractPayload(Document document) {
        String id = textContent(document, "id");
        String title = textContent(document, "title");

        List<String> references = XmlReferenceExtractor.extractReferences(document);
        return new XmlPayload(id, title, references);
    }

    private String textContent(Document document, String tagName) {
        var nodes = document.getElementsByTagName(tagName);
        if (nodes.getLength() == 0 || nodes.item(0).getTextContent() == null) {
            return "";
        }
        return nodes.item(0).getTextContent().trim();
    }

    private String resolveWhitelistedReference(String url) {
        URI uri = URI.create(url);

        if (!"https".equalsIgnoreCase(uri.getScheme())) {
            throw new IllegalArgumentException("Nur HTTPS-URLs sind erlaubt.");
        }

        String host = uri.getHost();
        if (host == null || !ALLOWED_HOSTS.contains(host.toLowerCase())) {
            throw new IllegalArgumentException("Unbefugter Zugriff auf externe Ressourcen wurde blockiert.");
        }

        try {
            HttpClient client = HttpClient.newBuilder()
                    .connectTimeout(Duration.ofSeconds(3))
                    .followRedirects(HttpClient.Redirect.NEVER)
                    .build();

            HttpRequest request = HttpRequest.newBuilder(uri)
                    .timeout(Duration.ofSeconds(5))
                    .GET()
                    .build();

            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

            if (response.statusCode() < 200 || response.statusCode() >= 300) {
                throw new IllegalArgumentException("Externe Ressource konnte nicht sicher geladen werden.");
            }

            return response.body();
        } catch (Exception e) {
            throw new IllegalArgumentException("Fehler beim sicheren Auflösen der Referenz.", e);
        }
    }
}
