### 4) Referenz-Extraktion aus dem XML

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlReferenceExtractor.java
package com.example.xmlapi.xml;

import org.w3c.dom.Document;
import org.w3c.dom.NodeList;

import java.util.ArrayList;
import java.util.List;

public final class XmlReferenceExtractor {

    private XmlReferenceExtractor() {
    }

    public static List<String> extractReferences(Document document) {
        NodeList nodes = document.getElementsByTagName("reference");
        List<String> references = new ArrayList<>();

        for (int i = 0; i < nodes.getLength(); i++) {
            String value = nodes.item(i).getTextContent();
            if (value != null && !value.isBlank()) {
                references.add(value.trim());
            }
        }

        return references;
    }
}
