## 4) XML Query Builder

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerXmlQueryBuilder.java
package com.example.customerapi.service.xml;

import org.springframework.stereotype.Component;

import java.util.Objects;

@Component
public class CustomerXmlQueryBuilder {

    public String buildSearchQuery(String customerName) {
        String safeName = Objects.requireNonNull(customerName, "customerName must not be null").trim();
        if (safeName.isEmpty()) {
            throw new IllegalArgumentException("customerName must not be blank");
        }

        return """
                <customerSearch>
                    <customerName>%s</customerName>
                </customerSearch>
                """.formatted(escapeXml(safeName));
    }

    private String escapeXml(String input) {
        return input
                .replace("&", "&amp;")
