## 6) XSD-validierendes Repository

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureXmlCustomerRepository.java
package com.example.customerapi.service.xml;

import com.example.customerapi.web.dto.CustomerResponse;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

import javax.xml.XMLConstants;
import javax.xml.transform.dom.DOMSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import javax.xml.validation.Validator;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Objects;

public class SecureXmlCustomerRepository {

    private final String xmlPath;
    private final String xsdPath;
    private final SecureXmlParser secureXmlParser;

    public SecureXmlCustomerRepository(String xmlPath, String xsdPath, SecureXmlParser secureXmlParser) {
        this.xmlPath = Objects.requireNonNull(xmlPath, "xmlPath must not be null");
        this.xsdPath = Objects.requireNonNull(xsdPath, "xsdPath must not be null");
        this.secureXmlParser = Objects.requireNonNull(secureXmlParser, "secureXmlParser must not be null");
    }

    public CustomerResponse findCustomerByQueryXml(String queryXml) {
        validateAgainstXsd(queryXml);

        Document queryDocument = secureXmlParser.parseXml(queryXml);
        String customerName = queryDocument.getDocumentElement()
                .getElementsByTagName("customerName")
                .item(0)
                .getTextContent();

        Document customersDocument = loadAndValidateCustomersXml();
        return extractMatchingCustomer(customersDocument, customerName);
    }

    private void validateAgainstXsd(String xml) {
        try {
            SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            Schema schema = schemaFactory.newSchema(loadResource(xsdPath));
            Validator validator = schema.newValidator();
            validator.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            validator.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            validator.validate(new DOMSource(secureXmlParser.parseXml(xml)));
        } catch (Exception ex) {
            throw new SecureXmlProcessingException("XML query validation failed", ex);
        }
    }

    private Document loadAndValidateCustomersXml() {
        try {
            Document customersDocument = secureXmlParser.parseXml(new String(loadResourceAsBytes(xmlPath), StandardCharsets.UTF_8));

            SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            Schema schema = schemaFactory.newSchema(loadResource(xsdPath));
            Validator validator = schema.newValidator();
            validator.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            validator.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            validator.validate(new DOMSource(customersDocument));
            return customersDocument;
        } catch (Exception ex) {
            throw new SecureXmlProcessingException("Customer XML validation failed", ex);
        }
    }

    private CustomerResponse extractMatchingCustomer(Document customersDocument, String customerName) {
        NodeList customers = customersDocument.getElementsByTagName("customer");
        for (int i = 0; i < customers.getLength(); i++) {
            Element customer = (Element) customers.item(i);
            String name = textOf(customer, "name");
            if (customerName.equalsIgnoreCase(name)) {
                return new CustomerResponse(
                        textOf(customer, "id"),
                        name,
                        textOf(customer, "email")
                );
            }
        }
        throw new CustomerNotFoundException("Customer not found: " + customerName);
    }

    private String textOf(Element parent, String tagName) {
        NodeList nodes = parent.getElementsByTagName(tagName);
        if (nodes.getLength() == 0 || nodes.item(0) == null) {
            return "";
        }
        return nodes.item(0).getTextContent();
    }

    private org.w3c.dom.Source loadResource(String resourcePath) {
        throw new UnsupportedOperationException("Resource loading is implemented via classpath in the application context");
    }

    private byte[] loadResourceAsBytes(String resourcePath) {
        try (InputStream in = getClass().getClassLoader().getResourceAsStream(stripClasspathPrefix(resourcePath))) {
            if (in == null) {
                throw new IllegalStateException("Resource not found: " + resourcePath);
            }
            return in.readAllBytes();
        } catch (Exception ex) {
            throw new SecureXmlProcessingException("Failed to load resource: " + resourcePath, ex);
        }
    }

    private javax.xml.transform.Source loadResource(String resourcePath) {
        InputStream in = getClass().getClassLoader().getResourceAsStream(stripClasspathPrefix(resourcePath));
        if (in == null) {
            throw new IllegalStateException("Resource not found: " + resourcePath);
        }
        return new javax.xml.transform.stream.StreamSource(in);
    }

    private String stripClasspathPrefix(String resourcePath) {
        return resourcePath.startsWith("classpath:") ? resourcePath.substring("classpath:".length()) : resourcePath;
    }
}
