## 7) Rate Limiting

Für produktive Systeme ist ein dediziertes Rate-Limiting-Framework sinnvoll. Unten ist eine einfache, sichere In-Memory-Variante als Beispiel. Sie ist bewusst konservativ und gibt keine internen Details preis.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimitService.java
package com.example.securefetcher.security;

import com.example.securefetcher.exception.RateLimitExceededException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

@Service
public class RateLimitService {

    private final int maxRequestsPerWindow;
    private final long windowSeconds;
    private final Map<String, WindowCounter> counters = new ConcurrentHashMap<>();

    public RateLimitService(
            @Value("${app.rate-limit.max-requests:30}") int maxRequestsPerWindow,
            @Value("${app.rate-limit.window-seconds:60}") long windowSeconds
    ) {
        this.maxRequestsPerWindow = maxRequestsPerWindow;
        this.windowSeconds = windowSeconds;
    }

    public void check(String clientIp) {
        long now = Instant.now().getEpochSecond();

        WindowCounter counter = counters.compute(clientIp, (ip, existing) -> {
            if (existing == null || now - existing.windowStart >= windowSeconds) {
                return new WindowCounter(now, new AtomicInteger(1));
            }
            existing.counter.incrementAndGet();
            return existing;
        });

        if (counter.counter.get() > maxRequestsPerWindow) {
            throw new RateLimitExceededException();
        }
    }

    private static final class WindowCounter {
        private final long windowStart;
        private final AtomicInteger counter;

        private WindowCounter(long windowStart, AtomicInteger counter) {
            this.windowStart = windowStart;
            this.counter = counter;
